        "task": "Experimentam cu tipuri nepotrivite",
        "steps": [
          "Ce se intampla dacă facem: int x = 3.7;? (se pierde partea zecimala!)",
          "Dar: float y = 5;? (funcționează, devine 5.0)",
          "Incercati: string s = 123; - eroare! De ce?"
        ],
        "teacher_support": "Discutie despre conversia implicita și erori de tip"
      }
